from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NrmtracecuParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mnc, mcc = self.enb_ent_config['mnc'], self.enb_ent_config['mcc']
        self.set_parameter('actCellTraceReportingCU', 'true')
        self.set_parameter('actPCMDReporting', 'true')
        self.set_parameter('cellMaxActiveUEsTraced', '100')
        self.set_parameter('jobType', 'TraceOnly')
        self.set_struct_parameter('nrRanTraceReference', [
            {
                'mcc': mcc,
                'mnc': mnc,
                'mncLength': self.get_len_str(mnc),
                'traceId': '1',
            }
        ])
        self.set_parameter('nrTceIdentifier', '1')
